module freq_divbyodd #(
    parameter NUM_DIV = 5
) (
    input clk,
    input rst_n,
    output reg clk_div
);


reg [2:0] cnt1, cnt2;
reg clk_div1, clk_div2;

always @* begin
    if(cnt1 == ((NUM_DIV/2)-1))
        clk_div1 = ~clk_div1;
        cnt1 = cnt1 + 1;
end

always @* begin
    if(cnt2 == ((NUM_DIV/2)-1))
        clk_div2 = ~clk_div2;
        cnt2 = cnt2 + 1;
end

assign clk_div = clk_div1 | clk_div2;
endmodule
